# typed: strict
# frozen_string_literal: true

# Generated by scripts/formula.ts in tab0inc/happen for each release; edits here are overwritten.
class Happen < Formula
  desc "Message channel between you and a supervising Claude Code session"
  homepage "https://github.com/tab0inc/happen-releases"
  license :cannot_represent

  depends_on :macos

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.4.0/happen_0.4.0_darwin_arm64.tar.gz"
      sha256 "d60aad2e78214ac26039a656c2aecc0085b0a880513de5a913c9d6cc0fdc07bf"
    else
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.4.0/happen_0.4.0_darwin_amd64.tar.gz"
      sha256 "0ad0137c40d4714b6c496dc529575e4b6abad84c5a538535c17b6e80588285d6"
    end
  end

  def install
    bin.install "happen"
  end

  def caveats
    <<~EOS
      Prepare this Mac once, then start the server (it also starts at login):
        happen setup
        brew services start happen
      Then connect a browser:
        happen open
      Start a lead: tell Claude Code to run happen skill --channel <channel>
      and follow it, or type in the session:
        ! happen skill --channel <channel>
    EOS
  end

  service do
    run [opt_bin/"happen", "serve"]
    keep_alive true
    log_path var/"log/happen.log"
    error_log_path var/"log/happen.log"
    environment_variables PATH: std_service_path_env
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/happen version")
  end
end
